insert into public."SiteContent" ("id","section","eyebrow","title","titleAccent","titleEnd","description","buttonText","buttonLink","buttonText2","buttonLink2","image","updatedAt","createdAt") values ('cmunl3d7f0000ne808q6glt08','hero','বাংলাদেশের #১ বিড়াল কমিউনিটি','বাংলাদেশে বিড়াল, খাবার ও','ভেট কোথায় পাবেন?','এখানেই খুঁজে নিন।','বিরালবন্ড হলো বাংলাদেশের বিড়াল তথ্য ও অনুসন্ধান প্ল্যাটফর্ম। কোথায় বিড়াল পাওয়া যায়, কোথায় বিড়ালের খাবার পাওয়া যায়, কোথায় পশু হাসপাতাল আছে — সব তথ্য এক জায়গায়।','বিড়াল কোথায় পাব','/breeds','ভেট খুঁজুন','/vets',null,'2026-09-30T04:14:11.144Z','2026-09-30T04:07:11.260Z') on conflict do nothing;
