insert into public."SiteContent" ("id","section","eyebrow","title","titleAccent","titleEnd","description","buttonText","buttonLink","buttonText2","buttonLink2","image","updatedAt","createdAt") values ('cmunl3d7i0002ne80b51k0k2x','food','বিড়ালের খাবার কোথায় পাওয়া যায়','ক্যাট','ফুড ফাইন্ডার',null,'কোথায় বিড়ালের খাবার পাওয়া যায় তা খুঁজুন। ব্র্যান্ড ও এলাকা অনুযায়ী খাবারের দোকানের তথ্য পান।',null,null,null,null,null,'2026-09-30T04:07:11.263Z','2026-09-30T04:07:11.263Z') on conflict do nothing;
