insert into public."Breed" ("id","name","bnName","origin","temperament","lifespan","weight","rarity","category","description","careLevel","goodWithKids","hypoallergenic","image","accent","createdAt","updatedAt") values ('persian-seed','Persian','পারসিয়ান বিরাল','Iran (Persia)','Calm, gentle, affectionate','12–17 years','3–5.5 kg','Premium','Pedigree','The Persian is the aristocrat of the cat world — beloved in Dhaka households for its luxurious long coat, sweet round face and serene temperament. Perfect for apartment living and families with children.','High',true,false,'https://images.unsplash.com/photo-1518791841217-8f162f1e1131?w=800&q=80','amber','2026-09-27T03:02:51.892Z','2026-09-27T03:02:51.892Z') on conflict do nothing;
