insert into public."Breed" ("id","name","bnName","origin","temperament","lifespan","weight","rarity","category","description","careLevel","goodWithKids","hypoallergenic","image","accent","createdAt","updatedAt") values ('british-shorthair-seed','British Shorthair','ব্রিটিশ শর্টহেয়ার','United Kingdom','Quiet, loyal, easygoing','14–20 years','4–8 kg','Premium','Pedigree','With their plush teddy-bear coats and round copper eyes, British Shorthairs are calm, dignified companions. They are undemanding yet deeply loyal to their families.','Easy',true,false,'https://images.unsplash.com/photo-1574158622682-e40e69881006?w=800&q=80','rose','2026-09-27T03:02:51.896Z','2026-09-27T03:02:51.896Z') on conflict do nothing;
insert into public."Breed" ("id","name","bnName","origin","temperament","lifespan","weight","rarity","category","description","careLevel","goodWithKids","hypoallergenic","image","accent","createdAt","updatedAt") values ('siamese-seed','Siamese','সিয়ামিজ','Thailand (Siam)','Vocal, social, intelligent','12–20 years','3–5 kg','Premium','Pedigree','Siamese cats are famous for their striking blue almond eyes and chatty personalities. They form intense bonds with their humans and love to "converse" throughout the day.','Moderate',true,false,'https://images.unsplash.com/photo-1561948955-570b270e7c36?w=800&q=80','cyan','2026-09-27T03:02:51.897Z','2026-09-27T03:02:51.897Z') on conflict do nothing;
