insert into public."Breed" ("id","name","bnName","origin","temperament","lifespan","weight","rarity","category","description","careLevel","goodWithKids","hypoallergenic","image","accent","createdAt","updatedAt") values ('ragdoll-seed','Ragdoll','র‍্যাগডল','California, USA','Docile, affectionate, floppy','13–18 years','4.5–9 kg','Exotic','Pedigree','Ragdolls literally go limp with relaxation when picked up — hence the name. They are devoted, dog-like companions who greet their humans at the door.','Moderate',true,false,'/cats/ragdoll.png','violet','2026-09-27T03:02:51.899Z','2026-09-27T03:18:39.414Z') on conflict do nothing;
