insert into public."Article" ("id","title","category","excerpt","content","author","readTime","image","tags","featured","createdAt","updatedAt") values ('cmuj8h3bq000roe50s4o6r55t','The Complete Guide to Feeding Your Persian Cat in Bangladesh','Nutrition','Persian cats need a specific diet to keep their coat glossy and digestion smooth. Here is everything Bangladeshi cat parents should know.','Persian cats are prone to hairballs and have a unique jaw shape that makes eating difficult with standard kibble. Always choose breed-specific food like Royal Canin Persian. Provide fresh water daily — a ceramic fountain encourages drinking. Avoid raw fish and milk; many cats are lactose intolerant. Stick to measured portions twice daily to prevent obesity, which Persians are prone to.','Dr. Farhana Yasmin',7,null,'persian,diet,nutrition',true,'2026-09-27T03:02:51.926Z','2026-09-27T03:02:51.926Z') on conflict do nothing;
insert into public."Article" ("id","title","category","excerpt","content","author","readTime","image","tags","featured","createdAt","updatedAt") values ('cmuj8h3bq000soe508ekphl4e','Monsoon Care: Keeping Your Cat Safe During Bangladesh''s Rainy Season','Health','Damp weather brings fleas, fungal infections and chill. Here is how to keep your cat cosy and healthy through the barsa.','During the monsoon, keep your cat indoors, dry and warm. Use a dehumidifier or air-conditioner to control moisture. Check ears weekly for fungal infections. Apply a flea-and-tick preventative like Seresto. Brush regularly to prevent matting. If your cat gets wet, towel-dry thoroughly — never use a human hair dryer on hot. Watch for sneezing or watery eyes, common signs of cat flu in humid weather.','Dr. Mahmudul Hasan',6,null,'monsoon,health,seasonal',true,'2026-09-27T03:02:51.927Z','2026-09-27T03:02:51.927Z') on conflict do nothing;
insert into public."Article" ("id","title","category","excerpt","content","author","readTime","image","tags","featured","createdAt","updatedAt") values ('cmuj8h3br000toe50zb1vfbqh','Litter Training Your Kitten in 5 Simple Steps','Behavior','New kitten parent? Litter training is easier than you think. Follow this proven five-step method used by rescues across Dhaka.','1) Choose a low-sided litter box kittens can climb into. 2) Use unscented clumping litter — kittens have sensitive noses. 3) Place the kitten in the box after meals and naps. 4) Gently scratch their front paws in the litter. 5) Praise and reward with a treat. Never punish accidents — clean them with an enzymatic cleaner. Most kittens are reliably trained within two weeks.','BiralBond Editorial',5,null,'kitten,training,litter',false,'2026-09-27T03:02:51.928Z','2026-09-27T03:02:51.928Z') on conflict do nothing;
insert into public."Article" ("id","title","category","excerpt","content","author","readTime","image","tags","featured","createdAt","updatedAt") values ('cmuj8h3bs000uoe50g87g0x1d','Grooming Your Long-Haired Cat: A Step-by-Step Routine','Grooming','Long-haired beauties need daily attention. Build a stress-free grooming routine that you and your cat will both enjoy.','Long-haired breeds like Persians, Maine Coons and Ragdolls need daily brushing to prevent painful mats. Use a wide stainless steel comb first, then a slicker brush. Bath every 4–6 weeks with a cat-specific shampoo. Check eyes daily — flat-faced breeds tear up. Trim nails every two weeks. Start grooming as kittens with short, treat-filled sessions so they learn to love it.','Sadia Islam',8,null,'grooming,long-hair,routine',true,'2026-09-27T03:02:51.928Z','2026-09-27T03:02:51.928Z') on conflict do nothing;
insert into public."Article" ("id","title","category","excerpt","content","author","readTime","image","tags","featured","createdAt","updatedAt") values ('cmuj8h3bs000voe503zlctts6','Vaccination Schedule Every Bangladeshi Cat Parent Must Follow','Health','From FVRCP to rabies, here is the complete vaccination calendar recommended by Bangladeshi veterinarians.','Core vaccines for cats in Bangladesh: FVRCP (feline distemper) at 8, 12 and 16 weeks, then annually. Rabies at 12–16 weeks, then annually. Optional but recommended: FeLV (feline leukaemia) for outdoor cats. Keep a vaccination card and never miss a booster. Vaccines cost ৳800–৳1,500 per dose and are available at all major vet clinics in Dhaka, Chattogram, Sylhet and Khulna.','Dr. Anisur Rahman',6,null,'vaccine,health,schedule',false,'2026-09-27T03:02:51.929Z','2026-09-27T03:02:51.929Z') on conflict do nothing;
insert into public."Article" ("id","title","category","excerpt","content","author","readTime","image","tags","featured","createdAt","updatedAt") values ('cmuj8h3bt000woe5070rjv5mq','Caring for Your Senior Cat (10+ Years)','Senior','Older cats need gentler routines, softer food and more frequent vet visits. Here is how to make their golden years truly golden.','Senior cats sleep more, eat less and may develop arthritis or kidney issues. Switch to senior-formula food, easily warmed. Add ramps to favourite spots so they don''t jump. Provide a low-sided litter box. Schedule vet check-ups every 6 months with bloodwork. Watch for changes in drinking, appetite or litter box habits — early detection saves lives.','Dr. Nazmun Nahar',7,null,'senior,health,care',false,'2026-09-27T03:02:51.930Z','2026-09-27T03:02:51.930Z') on conflict do nothing;
insert into public."CommunityPost" ("id","author","avatar","title","body","category","city","likes","comments","image","createdAt","updatedAt") values ('cmuj8h3bu000xoe5004agie4i','Tahmid Karim','TK','My rescue kitten just discovered the mirror!','After three weeks of hiding, Mochi finally noticed herself in the wardrobe mirror. The slow-blink fest that followed melted my heart. Sharing a photo below.','Story','Dhaka',142,23,null,'2026-09-27T03:02:51.930Z','2026-09-27T03:02:51.930Z') on conflict do nothing;
insert into public."CommunityPost" ("id","author","avatar","title","body","category","city","likes","comments","image","createdAt","updatedAt") values ('cmuj8h3bv000yoe5009xand3s','Labiba Rahman','LR','Best wet food brand for a picky Persian?','My 3-year-old Persian Bagha has suddenly gone off his usual brand. Has anyone tried Sheba or Felix pouches available in Dhaka? Looking for recommendations that won''t break the bank.','Question','Dhaka',38,41,null,'2026-09-27T03:02:51.931Z','2026-09-27T03:02:51.931Z') on conflict do nothing;
insert into public."CommunityPost" ("id","author","avatar","title","body","category","city","likes","comments","image","createdAt","updatedAt") values ('cmuj8h3bv000zoe50sh8r7s32','Sajid Ahmed','SA','Organising a cat meet-up in Chattogram this month','Calling all Chattogram cat parents! Planning a casual meet-up at Polo Ground on the last Saturday of the month. Bring your kitties (in carriers) and let''s swap stories. RSVP below.','Discussion','Chattogram',87,56,null,'2026-09-27T03:02:51.932Z','2026-09-27T03:02:51.932Z') on conflict do nothing;
insert into public."CommunityPost" ("id","author","avatar","title","body","category","city","likes","comments","image","createdAt","updatedAt") values ('cmuj8h3bw0010oe50scdk1s28','Maliha Chowdhury','MC','Tofu litter changed my life (and my nose)','Switched from clay to tofu litter two weeks ago. Zero dust, zero smell, and it flushes straight down the toilet. My Bengal''s asthma has improved dramatically. Highly recommend.','Advice','Sylhet',213,34,null,'2026-09-27T03:02:51.932Z','2026-09-27T03:02:51.932Z') on conflict do nothing;
