insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2d0000oea7fxda1gyw','Tahmid Karim','Cat parent of 2','Dhaka','TK',5,'I adopted my first rescue through BiralBond and the experience was seamless. The team guided me through every step — from choosing the right kitten to the first vet visit. Mochi is now the queen of our house!','Mochi',true,'2026-09-27T03:20:10.982Z','2026-09-27T03:20:10.982Z') on conflict do nothing;
insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2f0001oea7du1rd5sl','Dr. Farhana Yasmin','Veterinarian','Dhaka','FY',5,'As a vet, I trust BiralBond''s care guides more than any other Bangladeshi resource. They''re accurate, practical and genuinely put cats first. I recommend the platform to every new cat parent I meet.',null,true,'2026-09-27T03:20:10.983Z','2026-09-27T03:20:10.983Z') on conflict do nothing;
insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2g0002oea7rigzcfpw','Maliha Chowdhury','Bengal cat owner','Sylhet','MC',5,'The product range is incredible — finally a place in Bangladesh where I can get breed-specific food and organic litter without worrying about fakes. Delivery to Sylhet took just 2 days!','Leo',true,'2026-09-27T03:20:10.984Z','2026-09-27T03:20:10.984Z') on conflict do nothing;
insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2g0003oea795c3qtay','Sajid Ahmed','Community organiser','Chattogram','SA',5,'I organised our first Chattogram meet-up through the community forum and 40 cat parents showed up! BiralBond has built something special — a real, warm community, not just a marketplace.',null,false,'2026-09-27T03:20:10.985Z','2026-09-27T03:20:10.985Z') on conflict do nothing;
insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2h0004oea7d5ppeis9','Nadia Islam','Persian cat parent','Chattogram','NI',5,'When my Tom went missing, I posted on the Lost & Found board and within 6 hours a neighbour three streets away recognised him. BiralBond reunited us. I will be forever grateful.','Tom',true,'2026-09-27T03:20:10.986Z','2026-09-27T03:20:10.986Z') on conflict do nothing;
insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2i0005oea7rlblui5l','Rakib Hasan','First-time cat dad','Khulna','RH',5,'The care articles taught me everything I needed to know as a first-time cat parent — from litter training to vaccination schedules. Written in simple language, very practical for Bangladesh.','Tuntuni',false,'2026-09-27T03:20:10.986Z','2026-09-27T03:20:10.986Z') on conflict do nothing;
insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2j0006oea7e0plvucx','Sumaiya Akter','Rescue volunteer','Dhaka','SA',5,'Our rescue has placed over 50 kittens through BiralBond''s adoption listings. The adoption-first philosophy is real — they genuinely care about matching the right cat to the right home.',null,false,'2026-09-27T03:20:10.987Z','2026-09-27T03:20:10.987Z') on conflict do nothing;
insert into public."Testimonial" ("id","name","role","city","avatar","rating","quote","catName","featured","createdAt","updatedAt") values ('cmuj93d2j0007oea7ldt5hns1','Imran Ali','Scottish Fold owner','Sylhet','IA',4,'Booked a grooming session through the Services directory and was blown away. The provider came home, was gentle with my anxious cat, and sent before/after photos. Premium service indeed.','Bagha',false,'2026-09-27T03:20:10.988Z','2026-09-27T03:20:10.988Z') on conflict do nothing;
insert into public."CareTip" ("id","title","body","icon","category","createdAt","updatedAt") values ('cmuj93d2k0008oea7tffnyw7h','Fresh water, always','Cats are notoriously bad drinkers. Place 2–3 water bowls around the house, away from food. A ceramic fountain increases intake by up to 30%.','💧','Daily','2026-09-27T03:20:10.988Z','2026-09-27T03:20:10.988Z') on conflict do nothing;
insert into public."CareTip" ("id","title","body","icon","category","createdAt","updatedAt") values ('cmuj93d2k0009oea7mo02whc2','Brush before meals','Link grooming to mealtime. Your cat will associate brushing with something positive and mats stay away.','🪮','Grooming','2026-09-27T03:20:10.989Z','2026-09-27T03:20:10.989Z') on conflict do nothing;
insert into public."CareTip" ("id","title","body","icon","category","createdAt","updatedAt") values ('cmuj93d2l000aoea7zu7oxf8b','Slow blink = I love you','When your cat slow-blinks at you, blink back slowly. It''s the feline "I trust you" signal.','👁️','Behavior','2026-09-27T03:20:10.989Z','2026-09-27T03:20:10.989Z') on conflict do nothing;
insert into public."CareTip" ("id","title","body","icon","category","createdAt","updatedAt") values ('cmuj93d2l000boea75rvvsbyw','One litter box per cat + one','Two cats? Three boxes. Place them in quiet, separate spots. Scoop daily, full change weekly.','🚽','Daily','2026-09-27T03:20:10.990Z','2026-09-27T03:20:10.990Z') on conflict do nothing;
insert into public."CareTip" ("id","title","body","icon","category","createdAt","updatedAt") values ('cmuj93d2m000coea7bu3j6ya0','Vertical space matters','Cats feel safe up high. A cat tree, wall shelves or a cleared bookshelf top reduces stress dramatically in small Dhaka apartments.','📈','Environment','2026-09-27T03:20:10.991Z','2026-09-27T03:20:10.991Z') on conflict do nothing;
insert into public."CareTip" ("id","title","body","icon","category","createdAt","updatedAt") values ('cmuj93d2n000doea7uky3dzwo','Play before meals','Hunt → catch → eat → groom → sleep. A 15-minute play session before food mimics this natural cycle and prevents midnight zoomies.','🪶','Behavior','2026-09-27T03:20:10.991Z','2026-09-27T03:20:10.991Z') on conflict do nothing;
